contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(
        uint128 vBase,
        uint128 vNft,
        uint56 changeFee,
        uint16 feeRate1,
        uint16 feeRate2,
        bytes32 merkleRoot
    ) public {
        require(feeRate1 <= 5000 && feeRate2 > 5000);

        // First initialization succeeds with feeRate1.
        c.initialize(address(0x01), address(0x02), vBase, vNft, changeFee, feeRate1, merkleRoot, false, false);

        bool firstParamsHold = c.baseToken() == address(0x01)
            && c.nft() == address(0x02)
            && c.virtualBaseTokenReserves() == vBase
            && c.virtualNftReserves() == vNft
            && c.changeFee() == changeFee
            && c.feeRate() == feeRate1
            && c.merkleRoot() == merkleRoot
            && c.initialized();

        // A second initialize must always revert, even with different parameters.
        bool reverted;
        try c.initialize(address(0x03), address(0x04), vBase + 1, vNft + 1, changeFee, feeRate2, bytes32(uint256(1)), true, true) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool stillOriginal = c.baseToken() == address(0x01)
            && c.nft() == address(0x02)
            && c.virtualBaseTokenReserves() == vBase
            && c.virtualNftReserves() == vNft
            && c.feeRate() == feeRate1
            && c.merkleRoot() == merkleRoot
            && c.initialized();

        assert(reverted && firstParamsHold && stillOriginal);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        uint128 vBase,
        uint128 vNft,
        uint56 changeFee,
        uint16 feeRate,
        uint256 inputAmount
    ) public {
        require(feeRate <= 5000);
        require(vNft > 0);
        require(inputAmount > 0 && inputAmount < 2**128);

        // Set up pool state (fresh pool => initialize succeeds).
        c.initialize(
            address(0x01),
            address(0x02),
            vBase,
            vNft,
            changeFee,
            feeRate,
            bytes32(0),
            false,
            false
        );

        // Quote a sale of inputAmount NFT-weight.
        uint256 outputAmount = uint256(vBase) * inputAmount / (uint256(vNft) + inputAmount);

        bool ok;
        uint256 netOutput;
        uint256 feeAmount;
        try c.sellQuote(inputAmount) returns (
            uint256 n,
            uint256 f,
            uint256
        ) {
            ok = true;
            netOutput = n;
            feeAmount = f;
        } catch {
            ok = false;
        }

        assert(
            !ok || (
                feeAmount == outputAmount * uint256(feeRate) / 10_000
                && netOutput + 2 * feeAmount <= outputAmount
            )
        );
    }

    receive() external payable {}
}

