contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties,
        uint256 inputAmount
    ) public {
        require(_feeRate <= 5_000, "fee rate too high");
        require(_virtualNftReserves > 0, "need positive nft reserves");
        require(inputAmount > 0, "need positive input");
        require(inputAmount <= type(uint128).max, "input overflow guard");

        c.initialize(
            _baseToken, _nft, _virtualBaseTokenReserves, _virtualNftReserves,
            _changeFee, _feeRate, _merkleRoot, _useStolenNftOracle, _payRoyalties
        );

        (uint256 netOutputAmount, uint256 feeAmount, uint256 protocolFeeAmount) = c.sellQuote(inputAmount);

        uint256 outputAmount = uint256(_virtualBaseTokenReserves) * inputAmount / (uint256(_virtualNftReserves) + inputAmount);
        uint256 expectedFee = outputAmount * _feeRate / 10_000;

        assert(
            c.initialized() &&
            c.feeRate() == _feeRate &&
            outputAmount + feeAmount == netOutputAmount + feeAmount + protocolFeeAmount + protocolFeeAmount &&
            feeAmount == expectedFee &&
            netOutputAmount + protocolFeeAmount + feeAmount == outputAmount &&
            netOutputAmount <= outputAmount
        );
    }

    receive() external payable {}
}

